package com.bplus.share;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.content.pm.ActivityInfo;import android.view.*;import android.widget.*;
public class VideoActivity extends Activity {
 private VideoView video;private boolean full;private int position;private Uri uri;
 @Override protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);String raw=getIntent().getStringExtra("uri");if(raw==null){finish();return;}uri=Uri.parse(raw);if(!"content".equals(uri.getScheme())&&!"file".equals(uri.getScheme())){finish();return;}position=b==null?0:b.getInt("position",0);LinearLayout root=Ui.col(this);root.setBackgroundColor(android.graphics.Color.BLACK);root.addView(Ui.topBar(this,getIntent().getStringExtra("name"),true,null));video=new VideoView(this);root.addView(video,Ui.lpW1());MediaController controls=new MediaController(this);controls.setAnchorView(video);video.setMediaController(controls);TextView screen=Ui.cta(this,getString(R.string.fullscreen));root.addView(screen);screen.setOnClickListener(v->{full=!full;setRequestedOrientation(full?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);getWindow().getDecorView().setSystemUiVisibility(full?View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY:View.SYSTEM_UI_FLAG_VISIBLE);});video.setOnPreparedListener(mp->{video.seekTo(position);video.start();controls.show(4000);});video.setOnErrorListener((mp,what,extra)->{new AlertDialog.Builder(this).setTitle(getString(R.string.video_unsupported)).setMessage(getString(R.string.video_fallback)).setNegativeButton(getString(R.string.back_chat),(d,n)->finish()).setPositiveButton(getString(R.string.external_open),(d,n)->{try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(uri,"video/*");i.setClipData(ClipData.newRawUri("video",uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){Toast.makeText(this,getString(R.string.no_file_app),1).show();}}).show();return true;});setContentView(root);video.setVideoURI(uri);}
 @Override protected void onPause(){if(video!=null){position=video.getCurrentPosition();video.pause();}super.onPause();}
 @Override protected void onResume(){super.onResume();if(video!=null&&position>0){video.seekTo(position);video.start();}}
 @Override protected void onSaveInstanceState(Bundle b){if(video!=null)b.putInt("position",video.getCurrentPosition());super.onSaveInstanceState(b);}
 @Override protected void onDestroy(){if(video!=null)video.stopPlayback();super.onDestroy();}
}
